{
  "groups": [
    {
      "group_id": "ultra_low_fixed_rate_holders",
      "rule": "rate_type == 'fixed' and origination_year == 2021 and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers with locked-in low fixed rates face significant payment shock upon renewal and are highly likely to shop around."
    },
    {
      "group_id": "variable_rate_strained_deposits",
      "rule": "rate_type == 'variable' and td_deposits_3m_change_cad < 0 and mortgage_rate_pct > 5.0",
      "rationale": "Variable rate holders experiencing declining deposit balances are under cash flow pressure and require proactive retention offers."
    },
    {
      "group_id": "high_equity_prime_investors",
      "rule": "insured_flag == False and credit_score_band == '720_plus' and has_investments == True",
      "rationale": "Affluent conventional borrowers with strong credit profiles represent high retention value and elevated rate sensitivity."
    },
    {
      "group_id": "large_family_budget_constrained",
      "rule": "n_children >= 2 and household_income_cad < 75000",
      "rationale": "Lower-income households with multiple dependents face heightened affordability pressure that influences their lender loyalty."
    },
    {
      "group_id": "self_employed_non_insured",
      "rule": "employment_status == 'self_employed' and insured_flag == False",
      "rationale": "Self-employed conventional borrowers face unique underwriting requirements that make them distinct candidates for targeted retention advisory."
    },
    {
      "group_id": "ontario_digital_first_borrowers",
      "rule": "province == 'ON' and channel == 'digital' and has_advisor == False",
      "rationale": "Tech-savvy urban borrowers without a dedicated advisor are prone to online rate shopping and fast switching."
    },
    {
      "group_id": "long_tenure_branch_loyalists",
      "rule": "td_tenure_months >= 89 and has_advisor == True and channel == 'branch'",
      "rationale": "Deeply embedded relationship clients who utilize branch channels tend to prioritize service continuity over marginal rate gains."
    }
  ]
}
